# Check for potential directory traversal vulnerabilities
def is_safe_filename(filename: str) -> bool:
    return not (os.path.isabs(filename) or '..' in filename or '/' in filename or '\\' in filename)

# Test the function with various filenames
test_filenames = ["valid_file.txt", "../invalid_file.txt", "/absolute_path.txt", "subdir/valid_file.txt"]
for fname in test_filenames:
    print(f"Filename '{fname}' is safe: {is_safe_filename(fname)}")
